package com.pocketwise.controller;
import java.util.List; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import org.springframework.validation.annotation.Validated; import org.springframework.security.core.Authentication; import jakarta.validation.Valid; import com.pocketwise.model.Expense; import com.pocketwise.repository.ExpenseRepository;
@RestController @RequestMapping("/api/expenses") @Validated public class ExpenseController {private final ExpenseRepository repo;public ExpenseController(ExpenseRepository r){repo=r;} @GetMapping public List<Expense> all(Authentication a){return repo.findByOwnerEmailOrderByDateDesc(a.getName());} @PostMapping @ResponseStatus(HttpStatus.CREATED) public Expense create(@Valid @RequestBody Expense e,Authentication a){e.setId(null);e.setOwnerEmail(a.getName());return repo.save(e);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable String id,Authentication a){Expense e=repo.findById(id).filter(x->a.getName().equals(x.getOwnerEmail())).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Expense not found"));repo.delete(e);}}
